r_id": "{{customer_id}}"}, "descriptions": {"outcome": "Use only the selected terminal outcome: promise, paid, transferred, no_promise, not_verified, or not_reached.", "reason": "Required except for promise and paid. Use only the source-defined reason valid for the outcome."}, "description": "Exactly one final tool call, only after the customer has been thanked and told goodbye. Do not call any tool afterward.", "config": {"timeoutMs": 10000, "maxRetries": 0}, "pre_process_code": "@code:close_body"}}, "_code_library": {"identity_result": "try:
